#define spirit_wolf_VC 2400

static Mesh build_from(const int16_t *pos, const uint32_t *col, int vcount) {
    Mesh mesh; mesh.vert_count = vcount; mesh.tri_count = vcount/3;
    uint32_t pairs = (vcount+1)/2;
    mesh.verts = (T3DVertPacked*)malloc_uncached(pairs*sizeof(T3DVertPacked));
    memset(mesh.verts, 0, pairs*sizeof(T3DVertPacked));
    for (int v=0; v<vcount; v++) {
        int pi=v/2, sub=v%2;
        if (sub==0) { mesh.verts[pi].posA[0]=pos[v*3]; mesh.verts[pi].posA[1]=pos[v*3+1]; mesh.verts[pi].posA[2]=pos[v*3+2]; mesh.verts[pi].rgbaA=col[v]; mesh.verts[pi].normA=0; }
        else        { mesh.verts[pi].posB[0]=pos[v*3]; mesh.verts[pi].posB[1]=pos[v*3+1]; mesh.verts[pi].posB[2]=pos[v*3+2]; mesh.verts[pi].rgbaB=col[v]; mesh.verts[pi].normB=0; }
    }
    return mesh;
}

void models_gen_init(void) {
    mesh_druid_model = build_from(druid_pos, druid_col, druid_VC);
    mesh_werewolf_model = build_from(werewolf_pos, werewolf_col, werewolf_VC);
    mesh_spirit_wolf_model = build_from(spirit_wolf_pos, spirit_wolf_col, spirit_wolf_VC);
    debugf("[MODELS] modelos reais assados.\n");
}
